quests[31767] = { id = 31767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht sie kalt!", description = "Wir haben sie weichgeklopft. Und jetzt wird es Zeit, sie zu erledigen!\n\nDie Allianz muss in dieser Festung ausgemerzt werden, und wir haben keinen Platz für Gefangene.\n\n<Der Anflug eines Lächelns huscht über Nazgrims Gesicht.>\n\nIhr wisst, was zu tun ist, {name}. Diese Feiglinge werden fliehen, sobald sie Gelegenheit dazu haben.\n\nSeht zu, dass es nicht so weit kommt!", sourceObjective = "Tötet 15 Truppen von Donnerwehr.", completion = "Gute Arbeit, {class}! Damit haben sie nicht gerechnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[31768] = { id = 31768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer ist immer die richtige Antwort", description = "Es ist nicht genug damit, dass wir ihre Streitkräfte vernichten. Nichts, was sie sich zunutze machen könnten, darf zurückbleiben!\n\nNehmt diese Leuchtpistole und feuert damit auf ihre Munitionsvorräte. Lasst nichts für sie übrig!", sourceObjective = "Zerstört 10 Stapel Munition von Donnerwehr.", completion = "Haha! Gute Arbeit, {name}.\n\nLasst nichts für sie übrig!", sourceObjectiveStatus = "unverified-source-field" }
quests[31769] = { id = 31769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schlag!", description = "Der Kapitän hat sich über uns verschanzt.\n\nDer Feigling hat seine Truppen verrecken lassen, während er sich vor unserer Wut versteckt hat! Typisch Allianz! Egal. Er kann sein Los nicht länger hinauszögern.\n\nIch werde mit meinen Marinesoldaten über die Mauern klettern, während Ihr einen Frontalangriff die Rampen hoch leitet. Setzt Eure Leuchtpistole bei der Munition neben den Barrikaden ein, um den Weg freizusprengen.\n\nWir werden uns oben wieder treffen und gemeinsam diesen Waschlappen von einem Kapitän ausschalten!", sourceObjective = "Tötet Hauptmann Doren in Donnerwehr.", completion = "Ein Luftstützpunkt - sie hatten die ganze Zeit über einen geheimen Stützpunkt! Wenn ich das gewusst hätte, hätte ich die Geschütze stärker bemannt - waahh -\n\n<Nazgrim wird blass und sein Körper verströmt eine mysteriöse dunkle Energie.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31770] = { id = 31770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid entweder auf unserer Seite oder...", sourceObjective = "Versucht, die Hilfe von Bürgermeister Honigtau in Honigtau zu gewinnen.", completion = "Eure Kämpfe haben in unserem kleinen Dorf große Verwüstung angerichtet!\n\nWir sind nicht an Eurem Krieg interessiert, werden Eure Verletzten aber nicht abweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31771] = { id = 31771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Angesicht der Konsequenzen", description = "Weder kenne ich die Geschichte des Krieges, den Ihr kämpft, noch interessiert sie mich besonders. Dieses Land zahlt negative Energie mit gleicher Münze heim. Der Hass, die Zweifel und die Gewalt, die Ihr hier gesät habt, sickern nun aus Pandaria hervor wie das Blut aus einer offenen Wunde.\n\nEure Taten haben überall in diesen Ruinen Unheil gestiftet! Räumt hinter Euch auf und trefft mich unten im Dorf - ich werde mein Bestes tun, zu erklären, was hier vor sich geht.", sourceObjective = "Tötet 20 Shaheimsuchungen und 7 Sha-Herolde.", completion = "Ich bin froh, dass Ihr die Verantwortung für Euer Handeln übernehmt. Unkontrolliert können negative Gefühle hier schnell Besitz von einem ergreifen; genau wie es bei dem, den Ihr \"Nazgrim\" nennt, geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[31772] = { id = 31772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prioritäten!", description = "Seht Euch bloß diese Sauerei an! Das ganze Bräu ist verdorben!\n\nTaran Zhu hat uns davor gewarnt mit Euch Außenseitern zu sprechen, ich nehme aber jede Hilfe an, die ich bekommen kann.\n\nWir waren nach Morgenblüte unterwegs, als der Kampf ausbrach. Und jetzt ist unser ganzes Bräu dahin!\n\nWollt Ihr es wiedergutmachen? Vielleicht findet Ihr ja ein paar Fässer mit Honigbräu, die nicht kaputt sind. Dann wäre nicht alles verloren.", sourceObjective = "Findet 6 Fässer mit Honigbräu auf der Honigtaulichtung.", completion = "Es ist nicht so viel wie ich gehofft hatte, doch es wird schon reichen. Hat wohl keinen Sinn, verschüttetem Bräu nachzutrauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[31773] = { id = 31773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirscherschwierigkeiten", description = "Die Tiere spielen alle verrückt!\n\nNormalerweise meiden die Pirscher das Dorf, doch jetzt scheinen wir sie nicht mehr fernhalten zu können. So habe ich sie noch nie gesehen!\n\nDer Bürgermeister hat die Shado-Pan gerufen, sie sind aber noch nicht alle da. Könnt Ihr Euch um die Pirscher kümmern, ehe sie einen von unseren Bauern in Stücke reißen?", sourceObjective = "Tötet 10 Sha-verseuchte Pirscher auf der Honigtaulichtung.", completion = "Euer Konflikt bei den Ruinen fängt also an, die einheimische Tierwelt zu verschmutzen? Das ist ausgesprochen beunruhigend - eine so intensive Reaktion habe ich noch nie beobachtet.\n\nDanke, dass Ihr das Dorf beschützt habt, obwohl es eine Tragödie ist, dass die armen Tiere sterben mussten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31774] = { id = 31774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Zin'Jun", description = "Nieti behauptet gesehen zu haben, wie Zin'Jun mit den restlichen Überlebenden das Schiff verlassen hat. Das heißt, er ist noch immer irgendwo da draußen.\n\nWir dürfen ihn nicht zurücklassen. Er könnte verletzt oder gar gefangen genommen worden sein!\n\nFindet Zin'Jun und bringt ihn zurück.", sourceObjective = "Findet Zin'jun irgendwo im Aufstieg der Wirbelnden Winde.", completion = "<Zin'Jun ist schwer verletzt, spürt aber, dass Ihr freundlich seid.>\n\nAffendinger! Überall diese Affendinger!", sourceObjectiveStatus = "unverified-source-field" }
quests[31775] = { id = 31775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Flugplatz", description = "Ich habe ihren geheimen Flugplatz gefunden, {name}: den Starkarmflugplatz. Schwer war es nicht, denn es wimmelt dort nur so von Truppen der Allianz.\n\n<Nazgrim spuckt auf den Boden.>\n\nSie denken, sie hätten uns ausgelöscht, aber wir sind die Horde! Wir kämpfen, bis zum Tod... und womöglich darüber hinaus. Lassen wir sie unseren Stahl kosten!", sourceObjective = "Tötet 15 Starkarmsoldaten auf dem Starkarmflugplatz.", completion = "Was das Beste daran ist, die Allianz in Pandaria zu töten? Es wird Monate dauern, bevor sie Verstärkung erhalten.\n\nDies Land wird der Horde gehören, {class}. Wir sind beinahe fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[31776] = { id = 31776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starkarmtaktiken", description = "Die Späherberichte vom Starkarmflugplatz liegen jetzt vor und ich habe einige Ziele hoher Priorität markiert.\n\nZwei gnomische Mechaniker sorgen dafür, dass die Allianz ständig Gyrokopter in der Luft hat. Schaltet die Mechaniker aus und die Anzahl der Gyrokopter wird zurückgehen.\n\nEin zwergischer Todesritter patrouilliert um die Basis. Er ist ein Abenteurer, genau wie Ihr, und höchst gefährlich.\n\nUnd dann noch ein Name, der mir bekannt ist: Korporal Jackson Silver. Er ist ein Held der Allianz und tödlich im Umgang mit der Armbrust.\n\nViel Glück, {name}.", sourceObjective = "Tötet Korporal Jackson Silver, Morgus Grimmbeil, Meisteringenieur Ritzelschwung und Gyromechanikerin Lavendelol.", progress = "Seid vorsichtig, {name}, sie sind keine gewöhnlichen Ziele.", completion = "Blut und Donner, {name}. Blut und Donner.", sourceObjectiveStatus = "unverified-source-field" }
quests[31777] = { id = 31777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runter kommen sie alle", description = "Ich habe hier drüben ein paar schultermontierte Raketenwerfer entdeckt.\n\nVielleicht waren's auch Feuerwerkskörper. Keine Ahnung. Ich gehe erst mal davon aus, dass es schultermontierte Raketenwerfer sind, bis das Gegenteil erwiesen ist.\n\nWas ich damit sagen will, ist, dass jemand mit Euren Fertigkeiten als {class} damit vermutlich sogar einen Hubschrauber aus der Luft schießen könnte. Wenn Ihr welche findet, zielt damit auf diese armselig konstruierten Gyrokopter.", sourceObjective = "Beschafft Euch auf dem Starkarmflugplatz Zugriff auf requirierte Feuerwerkszünder und setzt diese gegen 12 Starkarmgyrokopter ein.", progress = "Wart Ihr erfolgreich?", completion = "Ich hoffe, diese Ding-Dongs hatten Spaß bei der Party, die Ihr für sie geschmissen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31778] = { id = 31778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unverlässliche Verbündete", description = "Zu Anfang haben wir die Allianz als Freunde willkommen geheißen. Viele unserer Dorfbewohner haben sich freiwillig gemeldet, um ihnen beim Bau eines Flugplatzes zu helfen. Aber vor Kurzem ist uns klargeworden, dass sie eine Militärbasis errichten - nur einen Katzensprung von unserem Dorf entfernt.\n\nUnd was noch schlimmer ist: Ich befürchte, dass einige Dorfbewohner dort gegen ihren Willen festgehalten werden. Falls Ihr sie findet, {class}, dann lasst sie wissen, dass es an der Zeit ist, nach Hause zu kommen.", sourceObjective = "Bringt 12 Pandarenfreiwillige dazu, den Starkarmflugplatz zu verlassen.", completion = "Auch wenn ich nicht verstehen kann, wieso Ihr Euren Krieg in unser Land tragt, sehe ich doch deutlich, welche der beiden am Konflikt beteiligten Parteien sich tugendhafter verhält.\n\nIch danke Euch für Eure Hilfe, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31779] = { id = 31779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dunkle Innere", description = "Ihr seid da draußen nicht zufällig Hauptmann Doren begegnet, oder?\n\nDieser schleimige Allianzanführer muss sich hier irgendwo versteckt halten. Auch, wenn er nicht in dieser Luftbasis war - weit kann er nicht sein. Durchkämmt das Gelände - und versucht, die Höhle südwestlich des Hauptflugplatzes zu durchsuchen. Ich will, dass die Allianz von hier verschwindet!", sourceObjective = "Tötet Hauptmann Doren.", progress = "Dann nichts wie ab mit Euch, {name}.", completion = "Die Allianztruppen wurden besiegt. Ihr, Nazgrim, Kiryn, Gorrok, Shokia und Nieti braucht eine Operationsbasis.\n\nDiese Flaggen müssen ausgetauscht werden.\n\nFür die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[31780] = { id = 31780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mac Donald", description = "Dieses Mal werdet Ihr mich nicht so leicht besiegen!", sourceObjective = "Besiegt Mac Donald in einem Haustierkampf.", completion = "Ich habe wohl noch viel zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31781] = { id = 31781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lindsay", description = "Ihr wollt es also noch mal mit mir aufnehmen? Ich nehme jede Herausforderung an!", sourceObjective = "Besiegt Lindsay in einem Haustierkampf.", completion = "Das hat überhaupt keinen Spaß gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[31782] = { id = 31782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umsturz", description = "Der Rat ist im Einklang, <Erwecker/Erweckerin>.\n\nUnser Ritual wird den Niedergang der Kaiserin herbeiführen und dazu beitragen, dass die Zukunft unseres großen Reichs gesichert ist.\n\nErlebt die Macht der Klaxxi!", sourceObjective = "Sprecht mit Klaxxi'va Ik in Klaxxi'vess.", completion = "Wir sind... geschlagen, Erwecker.\n\nEure Anstrengungen scheinen für unsere Sache unerlässlich geworden zu sein.\n\nIm Namen der verbleibenden Ratsmitglieder bitte ich Euch um Eure fortwährende Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31784] = { id = 31784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onyxquisit", progress = "Was habt Ihr da, {name}?", completion = "Es war die richtige Entscheidung, dieses Ei zu mir zu bringen. Wir werden gut darauf aufpassen, {name}." }
quests[31785] = { id = 31785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stufenaufstieg", description = "Gut, gut. Es ist wichtig, dass Ihr Eure Haustiere bei guter Gesundheit und kampfbereit haltet!\n\nAls nächstes möchte ich, dass Ihr mehrere Kämpfe bestreitet und ein Haustier auf Stufe 3 bringt. Danach kehrt Ihr zu mir zurück und wir überlegen, wie Ihr Eure eigenen Haustiere fangen könnt!", sourceObjective = "Lasst ein Haustier auf Stufe 3 aufsteigen.", completion = "Gut gemacht, {name}! Als Nächstes müsst Ihr lernen, Eure eigenen Kampfhaustiere zu fangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31786] = { id = 31786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makellose Fesseln der Rebellion", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31787] = { id = 31787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser Runenstein der Mogu", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Dieses Artefakt wird Lehrensuchern und Archäologen helfen, Pandarias Geschichte besser zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31788] = { id = 31788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser Arm aus Terrakotta", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Dieses Artefakt wird Lehrensuchern und Archäologen helfen, Pandarias Geschichte besser zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
