quests[31808] = { id = 31808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hiebe sind für alle da", description = "Kovok hat erstaunliche Fortschritte gemacht. Vielleicht haben die vielen Jahre des Winterschlafs sein Wachstum beeinflusst...\n\nWas immer auch dahinterstecken mag, es hätte zu keinem günstigeren Zeitpunkt passieren können. Ich glaube, es ist an der Zeit, seine Fähigkeiten auf die Probe zu stellen.\n\nDa Ihr so viel zu seiner Ausbildung beigetragen habt, finde ich es passend, dass Ihr ihm in seinem ersten Kampf zur Seite steht.\n\nIch habe ihn bereits an den Rand der Schneise geschickt. Sucht ihn auf und vernichtet die Armee der Shek'zeer!", sourceObjective = "Tötet 200 Mantis, während Ihr Kovok in der Schneise kontrolliert.", completion = "Durch Euren Geist konnte ich einige Szenen von der Schlacht sehen. Es schien mir ein echtes Massaker zu sein! Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[31809] = { id = 31809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbleibsel des Zorns", description = "Während Ihr die abgetrennte Klaue des besiegten Sha des Zorns betrachtet, kommt Euch der Gedanke, dass Ban Bärenherz, Kommandant der Shado-Pan in der Tonlongsteppe, bestimmt über Euren Sieg informiert werden möchte.", sourceObjective = "Bringt die Klaue des Zorns zu Ban Bärenherz bei der Shado-Pan-Garnison in der Tonlongsteppe.", progress = "<Ban schaut Euch eindringlich an.>\n\nIrgendetwas an Euch ist... anders. Verändert.", completion = "<Als Ihr Ban die Klaue überreicht, reißt er vor Erstaunen über Eure Leistung die Augen auf.>\n\nJetzt verstehe ich, welche Veränderung in Euch stattgefunden hat.\n\nIhr habt das Unmögliche vollbracht. Solange die Shado-Pan über dieses Land wachen, werden wir Euren Namen in Ehren halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31810] = { id = 31810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Himmel reiten", description = "Ich kann Euch nichts mehr beibringen, {name}.\n\nIhr habt Euch Eurer Schlange als würdig erwiesen.\n\nHeute werdet Ihr in unseren Orden aufgenommen. Seid Ihr bereit?", sourceObjective = "Schließt Euch dem Orden der Wolkenschlange an.", completion = "Heute verbrüdern wir uns.\n\nHerzlichen Glückwunsch zur Aufnahme in den Orden der Wolkenschlange. Reiten wir zusammen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31811] = { id = 31811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Himmel reiten", description = "Ich kann Euch nichts mehr beibringen, {name}.\n\nIhr habt Euch Eurer Schlange als würdig erwiesen.\n\nHeute werdet Ihr in unseren Orden aufgenommen. Seid Ihr bereit?", sourceObjective = "Schließt Euch dem Orden der Wolkenschlange an.", completion = "Heute verbrüdern wir uns.\n\nHerzlichen Glückwunsch zur Aufnahme in den Orden der Wolkenschlange. Reiten wir zusammen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31812] = { id = 31812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zunta, der Tierzähmer", description = "Wie ich sehe, habt Ihr Eure Fertigkeiten im Haustierkampf verbessert, {name}. Ich glaube, Ihr seid reif für eine echte Herausforderung.\n\nIhr findet Zunta nahe Tor'krens Hof, südlich von Orgrimmar. Er ist ein aufstrebender Wildtierzähmer und ich finde, Ihr solltet Euch mit ihm im Kampf messen!", sourceObjective = "Besiegt Zunta in einem Haustierkampf.", completion = "Ach, Varzok. Ja, ich kenne ihn gut. Euch hierher zu schicken, war kein Fehler.", sourceObjectiveStatus = "unverified-source-field" }
quests[31813] = { id = 31813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dagra die Grimmige", description = "Da unten gibt's noch 'ne Trainerin, der Ihr einen Kampf liefern solltet, um Euer Können auf die Probe zu stellen.\n\nDagra die Grimmige erwartet Euch am Nordhang des Dornenhügels östlich des Wegekreuzes. Wenn Ihr sie schlagt, habt Ihr womöglich drauf, was es braucht.", sourceObjective = "Besiegt Dagra die Grimmige in einem Haustierkampf.", progress = "Ich habe nichts zu befürchten. Man wird mich nicht besiegen!", completion = "Ihr kämpft mit der Entschlossenheit von jemandem, der die Niederlage weder fürchtet noch duldet. Ihr werdet es weit bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31814] = { id = 31814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Analynn", description = "Ohne eine echte Herausforderung ist jede Entschlossenheit ohne Wert.\n\nSucht die Straßen des westlichen Eschentals nach Analynn ab. Sie mag ein wenig... exzentrisch... erscheinen, aber eine gute Trainerin ist sie dennoch! Euch im Kampf gegen sie zu erproben, wird Eure Mannschaft stählen.", sourceObjective = "Besiegt Analynn in einem Haustierkampf.", completion = "Ihr versteht nicht. Ich habe keine Niederlage erlitten, sondern lediglich einen kleinen Rückschlag.", sourceObjectiveStatus = "unverified-source-field" }
quests[31815] = { id = 31815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zonya die Sadistin", description = "{name}, es hat sich eine seltene Gelegenheit ergeben, und ich glaube, Ihr werdet Interesse daran finden.\n\nZonya die Sadistin aus dem südlichen Steinkrallengebirge ist in die Kampfszene zurückgekehrt. Ich muss einfach vorschlagen, dass Ihr sie herausfordert, um Eure Fähigkeiten als <Zähmer/Zähmerin> weiter zu vervollkommnen.", sourceObjective = "Besiegt Zonya die Sadistin in einem Haustierkampf.", completion = "Hat Euch der Sieg geschmeckt? Es war Euer letzter. Ab hier wird es nicht leichter.", sourceObjectiveStatus = "unverified-source-field" }
quests[31816] = { id = 31816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluk der Verräter", description = "Seid Ihr bereit für ein Abenteuer? Bill der Pirat, der Star unter den örtlichen Tierzähmern am Schlingendornkap, hat eine offene Herausforderung an alle vorbereiteten Trainer herausgegeben!\n\nIhr könnt Bill den Piraten im südlichen Schlingendornkap finden, wo er die örtlichen Straßen auf der Suche nach potenziellen Kämpfen bereist.", sourceObjective = "Besiegt Bill den Piraten in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31817] = { id = 31817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merda Starkhuf", description = "Seid Ihr für einen echten Beweis Eures Könnens bereit, {race}?\n\nMerda Starkhuf hat ihr Lager an dem Ort aufgeschlagen, den sie in der Cenariuswildnis von Desolace Karnums Lichtung nennen. Gegen eine so starke Trainerin anzutreten, wird Eure Fertigkeiten auf den Prüfstand stellen, hm?", sourceObjective = "Besiegt Merda Starkhuf in einem Haustierkampf.", completion = "Der Widerstand von Desolace hält Eurem Wunsch zu wachsen nicht stand. Ich weiß Eure Mühe zu würdigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31818] = { id = 31818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zunta", description = "Ihr wollt es also noch mal mit mir aufnehmen?", sourceObjective = "Besiegt Zunta in einem Haustierkampf.", progress = "Ihr seid guter Gegner.", completion = "Hört auf! Genug! Ihr gewinnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31819] = { id = 31819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dagra die Grimmige", description = "Ihr seid diesen Berg erneut bestiegen, nur, um Eurem eigenen Untergang beizuwohnen.", sourceObjective = "Besiegt Dagra die Grimmige in einem Haustierkampf.", completion = "Unmöglich!", sourceObjectiveStatus = "unverified-source-field" }
quests[31820] = { id = 31820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Lehrer", description = "Ich habe jetzt mit den anderen Kindern aufgeholt, obwohl ich erst so spät angefangen habe. Endlich kann ich am planmäßigen Unterricht teilnehmen!\n\nIch habe Euch eine Schürze gemacht, um mich für all das zu bedanken, was Ihr für mich getan habt. Ich hoffe, sie gefällt Euch.", sourceObjective = "Nehmt Nomis Geschenk an.", completion = "Vielen lieben Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[31821] = { id = 31821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stufenaufstieg", description = "Gut, gut. Es ist wichtig, dass Ihr Eure Haustiere bei guter Gesundheit und kampfbereit haltet!\n\nAls nächstes möchte ich, dass Ihr mehrere Kämpfe bestreitet und ein Haustier auf Stufe 3 bringt. Danach kehrt Ihr zu mir zurück und wir überlegen, wie Ihr Eure eigenen Haustiere fangen könnt!", sourceObjective = "Lasst ein Haustier auf Stufe 3 aufsteigen.", completion = "Gut gemacht, {name}! Als Nächstes müsst Ihr lernen, Eure eigenen Kampfhaustiere zu fangen!", sourceObjectiveStatus = "unverified-source-field" }
