quests[31845] = { id = 31845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung macht den Meister: Meister Tsang", description = "Schön, dass Ihr wieder da seid, {name}. Ich sehe, Ihr seid zurückgekommen, um Eure Fertigkeiten zu verbessern. Sprecht mit Meister Tsang auf dem Ausbildungsgelände unter uns, um einen Übungskampf einzulegen.", sourceObjective = "Sprecht mit Meister Tsang auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihm ab.", completion = "Meister Tsang hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31846] = { id = 31846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung macht den Meister: Meister Hsu", description = "Schön, dass Ihr wieder da seid, {name}. Ich sehe, Ihr seid zurückgekommen, um Eure Fertigkeiten zu verbessern. Sprecht mit Meister Hsu auf dem Ausbildungsgelände unter uns, um einen Übungskampf einzulegen.", sourceObjective = "Sprecht mit Meister Hsu auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihm ab.", completion = "Ich höre von Meister Hsu, dass Eure Ausbildung zufriedenstellend verläuft. Kommt in Zukunft wieder zu mir, um Eure Ausbildung fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31847] = { id = 31847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieber ein Ende mit Schrecken als die Schreckensöde", description = "Ich bin mir sicher, dass viele unserer Verbündeten nach Eurem Sieg hier Eure Dienste in Anspruch nehmen wollen. Doch ich habe einen Hilferuf unserer Verteidiger an der Grenzmauer zur Schreckensöde erhalten.\n\nFalls Ihr ihnen helfen wollt, nehmt einen Drachen und meldet Euch bei Bogenmeisterin Li.", sourceObjective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31850] = { id = 31850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eric Davidson", description = "Aha, Ihr habt Euch also erneut in den Wald gewagt, um es im Kampf mit mir aufzunehmen. Ich nehme Eure dreiste Herausforderung meiner teuflischen Brut an.", sourceObjective = "Besiegt Eric Davidson in einem Haustierkampf.", completion = "Euer Mut zum Risiko wurde belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31851] = { id = 31851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bill Schildbuckel", description = "Ihr scheid wohl für die nächste Runde da, wasch?\n\nIch werd' Euch schon scheigen, warum man mich den Schrecken desch Talsch nennt!", sourceObjective = "Besiegt Bill Schildbuckel in einem Haustierkampf.", progress = "Ich hab' scho' Bescheresch geschehen... hick!", completion = "Heut mögt Ihr geschiegt haben, Kumpel, aber näschtesch Mal lasch ich Euch nicht scho ungeschoren davonkommen, jawoll!", sourceObjectiveStatus = "unverified-source-field" }
quests[31852] = { id = 31852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steven Lisbane", description = "Ihr wagt es, mich erneut herauszufordern? Diesmal glaube ich, dass unser Kampf zu meinen Gunsten ausgehen wird!", sourceObjective = "Besiegt Steven Lisbane in einem Haustierkampf.", progress = "Ich habe solchen Spaß an unseren Begegnungen.", completion = "Ein spannender Kampf! Grandios! Wirklich gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[31853] = { id = 31853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Mann an Bord!", description = "Habt Ihr gehört, {name}? Ich muss eine kampferprobte Mannschaft für eine gefährliche Mission zusammenstellen – es gibt Allianzler zu töten.\n\nIhr werdet mich begleiten!\n\nWir kehren nicht eher zurück, als unsere Aufgabe erfüllt ist, also packt Eure Sachen und macht Euch bereit.\n\nIhr findet mich an Bord eines neu in Dienst gestellten Luftschiffs über der Messerbucht.\n\nLasst mich ja nicht warten!", sourceObjective = "Sprecht mit General Nazgrim an Bord von Höllschreis Faust.", completion = "Willkommen an Bord von Höllschreis Faust, {name}!\n\nDas hier ist ihre Jungfernfahrt. Ist sie nicht eine Schönheit?", sourceObjectiveStatus = "unverified-source-field" }
quests[31854] = { id = 31854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Analynn", description = "Ich sehe, Ihr habt mich schon wieder gefunden. Ich nehme an, Ihr möchtet einen weiteren Kampf? So sei es.", sourceObjective = "Besiegt Analynn in einem Haustierkampf.", completion = "Eure Tiere sind völlig aus dem Häuschen über ihren Sieg. Ich hoffe, Euch geht es genauso.", sourceObjectiveStatus = "unverified-source-field" }
quests[31855] = { id = 31855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel der Ruhe - Setzt Eure Ausbildung fort", description = "Es ist Zeit, dass Ihr zum Gipfel der Ruhe zurückkehrt, um Eure Ausbildung fortzusetzen. Kehrt mithilfe der Zenpilgerfahrt dorthin zurück und sprecht bei Eurer Ankunft mit Meister Hight.", sourceObjective = "Reist mithilfe der Zenpilgerfahrt zum Gipfel der Ruhe. Sprecht bei Eurer Ankunft mit Meister Hight am Schrein des Ochsen.", completion = "Willkommen, {name}. Es ist Zeit, Eure Ausbildung fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31856] = { id = 31856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel der Ruhe - Beginnt Eure Ausbildung", description = "Es ist Zeit, dass Ihr zum Gipfel der Ruhe aufbrecht und Euch dort im Weg des Mönchs ausbilden lasst. Begebt Euch mithilfe der Zenpilgerfahrt dorthin und sprecht bei Eurer Ankunft mit Meister Hight.", sourceObjective = "Reist mithilfe der Zenpilgerfahrt zum Gipfel der Ruhe. Sprecht bei Eurer Ankunft mit Meister Hight am Schrein des Ochsen.", completion = "Willkommen, {name}. Es ist Zeit, mit Eurer Ausbildung zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
