quests[31862] = { id = 31862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zonya die Sadistin", description = "Die Beute läuft in das Revier des Raubtiers, ohne sich der Gefahr bewusst zu sein, in der sie sich befindet. Diesmal werdet Ihr Zonya keine Schwierigkeiten bereiten.", sourceObjective = "Besiegt Zonya die Sadistin in einem Haustierkampf.", completion = "Ihr glaubt, Ihr hättet gesiegt, ich werde jedoch mit jeder Niederlage stärker.", sourceObjectiveStatus = "unverified-source-field" }
