quests[31882] = { id = 31882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, {name}. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31883] = { id = 31883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, {name}. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
