quests[31885] = { id = 31885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, {name}. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31886] = { id = 31886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensort", description = "Shado-Pan-Bogenschützen halten kontinuierlich Wache über die Schreckensöde, von der Spitze des Schlangenrückens aus. Sie würden die Hilfe von jemand so Fähigem wie Euch, {class}, sicher willkommen heißen.\n\nNehmt einen Drachen und meldet Euch bei Bogenmeisterin Li.", sourceObjective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31887] = { id = 31887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustiertrainer: Kalimdor", description = "Es ist an der Zeit, Eure Kampffertigkeiten einer echten Prüfung zu unterziehen.\n\n Ihr könnt Steven Lisbane auf den Straßen im südlichen Teil des nördlichen Schlingendorntals finden. Sucht ihn und zeigt ihm, wer der bessere Zähmer ist!", sourceObjective = "Besiegt Steven Lisbane in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31888] = { id = 31888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustiertrainer: Kalimdor", description = "Es ist an der Zeit, Eure Kampffertigkeiten einer echten Prüfung zu unterziehen.\n\n Ihr könnt Steven Lisbane auf den Straßen im südlichen Teil des nördlichen Schlingendorntals finden. Sucht ihn und zeigt ihm, wer der bessere Zähmer ist!", sourceObjective = "Besiegt Steven Lisbane in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31889] = { id = 31889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Kalimdor", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn Kalimdor gibt es fünf Zähmer, die Ihr für mich besiegen sollt: Gluk den Verräter in Feralas, Grazzel den Großen in den Düstermarschen, Kela Grimmtotem in Tausend Nadeln, Zoltan im Teufelswald und Elena Flatterflug in der Mondlichtung.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit, voranzuschreiten.", sourceObjective = "Besiegt Gluk den Verräter, Grazzel den Großen, Kela Grimmtotem, Zoltan und Elena Flatterflug in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31890] = { id = 31890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustiertrainer: Kalimdor", description = "Es ist an der Zeit, Eure Kampffertigkeiten einer echten Prüfung zu unterziehen.\n\n Ihr könnt Steven Lisbane auf den Straßen im südlichen Teil des nördlichen Schlingendorntals finden. Sucht ihn und zeigt ihm, wer der bessere Zähmer ist!", sourceObjective = "Besiegt Steven Lisbane in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31891] = { id = 31891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Kalimdor", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn Kalimdor gibt es fünf Zähmer, die Ihr für mich besiegen sollt: Gluk den Verräter in Feralas, Grazzel den Großen in den Düstermarschen, Kela Grimmtotem in Tausend Nadeln, Zoltan im Teufelswald und Elena Flatterflug in der Mondlichtung.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit, voranzuschreiten.", sourceObjective = "Besiegt Gluk den Verräter, Grazzel den Großen, Kela Grimmtotem, Zoltan und Elena Flatterflug in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31892] = { id = 31892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustiertrainer: Kalimdor", description = "Dieselben Trainer, die Ihr bereits in Kalimdor besiegt habt, haben Euch erneut herausgefordert. Ohne Zweifel haben Sie Euren letzten Sieg nicht vergessen!\n\nSucht sie auf und beweist Euer Können!", sourceObjective = "Besiegt Elena Flatterflug, Kassandra Kabumm, Golbo den Großen, Zoltan und Kela Grimmtotem in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31893] = { id = 31893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustiertrainer: Kalimdor", description = "Dieselben fünf Trainer, die Ihr in Kalimdor besiegt habt, haben Euch törichterweise erneut zu einem Kampf herausgefordert.\n\nZeigt Ihnen keine Gnade!", sourceObjective = "Besiegt Elena Flatterflug, Kassandra Kabumm, Golbo den Großen, Zoltan und Kela Grimmtotem in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31894] = { id = 31894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein empfindliches Gleichgewicht", description = "Zum Shado-Pan berufen zu werden bedeutet, dass man sich dem Schutz des Gleichgewichts und der Harmonie dieses Landes verschreibt. Es ist unsere Pflicht, dieses Gleichgewicht aufrechtzuerhalten, {name}.\n\nDie Aktivitäten der Yaungol in Tonlong jedoch gefährden dieses Gleichgewicht und müssen aufgehalten werden, bevor es zu spät ist.\n\nWir haben Yaungol in den Sumpfbinsen gesichtet. Berichten zufolge sollen sie die Nebellauerer in der Gegend angreifen. Findet heraus warum, und setzt dem ein Ende!", sourceObjective = "Sprecht mit Orbiss in den Sumpfbinsen.", completion = "<Orbiss stöhnt unter Qualen.>\n\nSo so, die Shado-Pan haben Euch ausgesandt, um nachzusehen, was die Yaungol treiben? Nun, seht Ihr es jetzt?", sourceObjectiveStatus = "unverified-source-field" }
quests[31895] = { id = 31895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieber Schrecken als verrecken", description = "Es ist an der Zeit, den Ursprung zu suchen, {name}!\n\nDie Schützen der Shado-Pan halten von der Spitze des Schlangenrückens aus ohne Unterlass Wache über die Schreckensöde. Sie würden die Hilfe von jemandem mit Euren Fähigkeiten als {class} ganz sicher begrüßen.\n\nSucht Bogenmeisterin Li auf dem Schlangenrücken an der Grenze zur Schreckensöde auf.", sourceObjective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31897] = { id = 31897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Trixxy", description = "Wenn man nach den Meisterzähmern Kalimdors geht, seid Ihr der neue Star der Szene. Warum kommt Ihr nicht bei meinem Ausbildungsgelände in den Eisdistelbergen in Winterquell vorbei, damit ich Euch zeigen kann, wie es wirklich gemacht wird?", sourceObjective = "Besiegt die eiskalte Trixxy in einem Haustierkampf.", progress = "Ihr seid zäher als Ihr ausseht!", completion = "Ihr habt wohl wirklich Starpotenzial, oder? Nächstes Mal wird Euch das Glück weniger hold sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[31902] = { id = 31902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Östliche Königreiche", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn den Östlichen Königreichen gibt es fünf Zähmer, die Ihr für mich besiegen sollt: David Kosse im Hinterland, Deiza Seuchenhorn in den Östlichen Pestländern, Kortas Düsterhammer in der Sengenden Schlucht, Everessa in den Sümpfen des Elends und Kortas' Bruder Durin Düsterhammer in der Brennenden Steppe.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit für den nächsten Schritt.", sourceObjective = "Besiegt David Kosse, Deiza Seuchenhorn, Kortas Düsterhammer, Everessa und Durin Düsterhammer in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31903] = { id = 31903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Östliche Königreiche", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn den Östlichen Königreichen gibt es fünf Zähmer, die Ihr für mich besiegen sollt: David Kosse im Hinterland, Deiza Seuchenhorn in den Östlichen Pestländern, Kortas Düsterhammer in der Sengenden Schlucht, Everessa in den Sümpfen des Elends und Kortas' Bruder Durin Düsterhammer in der Brennenden Steppe.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit für den nächsten Schritt.", sourceObjective = "Besiegt David Kosse, Deiza Seuchenhorn, Kortas Düsterhammer, Everessa und Durin Düsterhammer in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31904] = { id = 31904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kassandra Kabumm", description = "Ich habe meine Haustiere mit neuen gyrotechnischen Ausbildungsmodulen geladen. Ihr seid erledigt!", sourceObjective = "Besiegt Kassandra Kabumm in einem Haustierkampf.", progress = "Ihr seid Abschaum!", completion = "Ich muss irgendwo eine Zeile falsch umgewandelt haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[31905] = { id = 31905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grazzel der Große", description = "Ihr seid zurück?! Ihr wollt wohl von einem schwarzen Drachen gefressen werden!", sourceObjective = "Besiegt Grazzel den Großen in einem Haustierkampf.", progress = "Da hab ich schon Besseres gesehen.", completion = "Es scheint fast so, als hätten meine Hübschen den Spaß am Kampf verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31906] = { id = 31906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kela Grimmtotem", description = "Ihr besitzt die Kühnheit, ein Mal mehr Fuß ins Land derer von Grimmtotem zu setzen, um mich herauszufordern? Ihr werdet Euren Entschluss bereuen!", sourceObjective = "Besiegt Kela Grimmtotem in einem Haustierkampf.", completion = "Merkt Euch meine Worte: Eines Tages werde ich Euch besiegen, und zwar bald.", sourceObjectiveStatus = "unverified-source-field" }
quests[31907] = { id = 31907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zoltan", description = "Ich werde von Tag zu Tag stärker. Widerstand ist zwecklos.", sourceObjective = "Besiegt Zoltan in einem Haustierkampf.", completion = "Diese Welt ist dem Untergang geweiht. Warum setzt Ihr Euch so leidenschaftlich zur Wehr?", sourceObjectiveStatus = "unverified-source-field" }
quests[31908] = { id = 31908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elena Flatterflug", description = "Ich sehe schon, Ihr seid bereit für ein weiteres Kräftemessen in den Lüften. Fliegen wir los!", sourceObjective = "Besiegt Elena Flatterflug in einem Haustierkampf.", completion = "Mein Flug hat ein jähes Ende gefunden. Heute tragt Ihr den Sieg davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[31909] = { id = 31909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Trixxy", description = "Halt! Eure letzte Begegnung hat Euch wohl endlich aufgewärmt, was? Das soll sich ändern.", sourceObjective = "Besiegt die eiskalte Trixxy in einem Haustierkampf.", progress = "Ihr zeigt keine Gnade. Ihr gefallt mir.", completion = "Ihr seid wirklich krass drauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[31910] = { id = 31910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "David Kosse", description = "Meine Forschungen haben sich für meine Trainingsmethoden als äußerst nützlich erwiesen. Dieses Mal werde ich Euch besiegen.", sourceObjective = "Besiegt David Kosse in einem Haustierkampf.", completion = "Womöglich ist meine Forschung doch noch nicht so ausgereift, wie ich angenommen hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[31911] = { id = 31911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deiza Seuchenhorn", description = "Noch habt Ihr den wahren Pfad der Untoten nicht eingeschlagen. Vielleicht wird Euch ein weiterer Kampf die Richtung weisen.", sourceObjective = "Besiegt Deiza Seuchenhorn in einem Haustierkampf.", completion = "Vielleicht birgt der Untod doch nicht die Antwort...", sourceObjectiveStatus = "unverified-source-field" }
quests[31912] = { id = 31912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kortas Düsterhammer", description = "Ich habe gehört, dass Ihr gegen meinen Bruder, diesen Narren, gekämpft habt. Er hat wohl verloren, was?\n\nDann darf ich wohl jetzt zeigen, was ich draufhabe!", sourceObjective = "Besiegt Kortas Düsterhammer in einem Haustierkampf.", completion = "Ihr seid keinen Deut besser als Durin. Es geht um die Ehre? Pah!", sourceObjectiveStatus = "unverified-source-field" }
quests[31913] = { id = 31913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everessa", description = "Ich glaube, ich komme langsam hinter die Geheimnisse dieses Orts... Bald schon werde ich nicht mehr aufzuhalten sein!", sourceObjective = "Besiegt Everessa in einem Haustierkampf.", completion = "Ich sehe, Ihr habt Eure eigenen Geheimnisse.", sourceObjectiveStatus = "unverified-source-field" }
quests[31914] = { id = 31914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durin Düsterhammer", description = "Seit meiner Zeit im Dienst des Feuerlords bin ich für alles gewappnet. Nichts, was Ihr mir entgegenschleudert, könnte mich erschüttern!", sourceObjective = "Besiegt Durin Düsterhammer in einem Haustierkampf.", completion = "Ich besieg' Euch, und wenn's das Letzte ist, was ich tue. Ich hab' nicht umsonst den ganz'n Weg hierher auf mich genomm'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[31915] = { id = 31915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Lydia Accoste", description = "Die Meisterzähmer in der Umgebung der Östlichen Königreiche reden schon von Euch. Ihr glaubt, Ihr seid nicht aufzuhalten? Ihr glaubt, dass Ihr <der wahre Großmeister/die wahre Großmeisterin> seid?\n\nDann kommt nur, {name}. Ich erwarte Euch am Gebirgspass der Totenwinde. Kommt, und Ihr werdet die vernichtende Niederlage erleben, die Euch von jeher gebührt.", sourceObjective = "Besiegt Lydia Accoste in einem Haustierkampf.", progress = "Eure Stärke ist anders als die der anderen...", completion = "Ich habe eine Ewigkeit, um zu trainieren. Ich werde Euch bezwingen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31916] = { id = 31916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Lydia Accoste", description = "Ihr möchtet mir noch einmal von Angesicht zu Angesicht gegenüberstehen? Diese Entscheidung werdet Ihr bereuen!", sourceObjective = "Besiegt Lydia Accoste in einem Haustierkampf.", completion = "Eure Strategie wird mir immer klarer. Am Ende ist Euch die Niederlage gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[31917] = { id = 31917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr des Zähmers", description = "Ihr könnt Euch jetzt kopfüber in waschechte Haustierkämpfe stürz'n. Kehrt zu Eurer Trainerin Marlene Trichdie nach Sturmwind zurück und macht Euch für das Abenteuer Eures Lebens bereit!", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Ich bin ja so stolz auf Euch, {name}. Ihr seid zu Großem bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[31918] = { id = 31918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr des Zähmers", description = "Wenn Ihr mich schlagen könnt, dann seid Ihr bereit für die ganz große Bühne! Sprecht mit Varzok in Orgrimmar.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Gut gemacht, {name}. Jetzt könnt Ihr Euch wirklich als Zähmer bezeichnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31919] = { id = 31919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Scherbenwelt", description = "Ihr habt die Meisterzähmer Kalimdors und der Östlichen Königreiche bezwungen, doch Eure nächste Herausforderung wird Euch auf eine sehr viel härtere Probe stellen.\n\nIn der Scherbenwelt gibt es vier Zähmer, die Ihr jetzt besiegen müsst: Nicki Mikrotech auf der Höllenfeuerhalbinsel, Ras'an in den Zangarmarschen, Narrok in Nagrand und Morulu den Älteren in Shattrath.\n\nBesiegt sie, wenn Ihr den Pfad zu wahrer Größe beschreiten wollt.", sourceObjective = "Besiegt Nicki Mikrotech, Ras'an, Narrok und Morulu den Älteren in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31920] = { id = 31920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Antari", description = "Leute wie Euch kenne ich zur Genüge: junge, naive Zähmer, die glauben, dass sie es verdienen, die Siegeslorbeeren auf dem Silbertablett gereicht zu bekommen.\n\nAber nicht mit mir! In mir habt Ihr Euren Meister gefunden, {class}. Ich, Blutritter Antari des Schattenmondtals, kann es kaum erwarten, Euch zu zeigen, wie es sich anfühlt, im Kampf ausgelöscht zu werden.", sourceObjective = "Besiegt Blutritter Antari in einem Haustierkampf.", completion = "Unmöglich! Ich kann nicht verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[31921] = { id = 31921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Scherbenwelt", description = "Ihr habt die Meisterzähmer Kalimdors und der Östlichen Königreiche bezwungen, doch Eure nächste Herausforderung wird Euch auf eine sehr viel härtere Probe stellen.\n\nIn der Scherbenwelt gibt es vier Zähmer, die Ihr jetzt besiegen müsst: Nicki Mikrotech auf der Höllenfeuerhalbinsel, Ras'an in den Zangarmarschen, Narrok in Nagrand und Morulu den Älteren in Shattrath.\n\nBesiegt sie, wenn Ihr den Pfad zu wahrer Größe beschreiten wollt.", sourceObjective = "Besiegt Nicki Mikrotech, Ras'an, Narrok und Morulu den Älteren in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31922] = { id = 31922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicki Mikrotech", description = "Meinen Berechnungen zufolge habe ich eine 32,333%-ige Chance zu siegen. Ich werde sie nutzen!", sourceObjective = "Besiegt Nicki Mikrotech in einem Haustierkampf.", completion = "Ich habe vergessen, die 1 zu übernehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31923] = { id = 31923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ras'an", description = "Ihr wollt wieder kämpfen? Ich glaube, ich bin besser geworden!", sourceObjective = "Besiegt Ras'an in einem Haustierkampf.", progress = "Wenn ich siege, nehmt Ihr mich dann mit nach Sturmwind?", completion = "Das war wohl nichts...", sourceObjectiveStatus = "unverified-source-field" }
quests[31924] = { id = 31924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narrok", description = "Ich möchte noch einmal kämpfen. Diese Grünschnäbel müssen stärker werden.", sourceObjective = "Besiegt Narrok in einem Haustierkampf.", completion = "Sieht so aus, als hätten diese Jungen noch viel Arbeit, bevor sie ihre volle Stärke erlangen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[31925] = { id = 31925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morulu der Ältere", description = "Seit unserem letzten Aufeinandertreffen habe ich viel gelernt. Wollt Ihr Euer Können erneut auf die Probe stellen?", sourceObjective = "Besiegt Morulu den Älteren in einem Haustierkampf.", completion = "Sogar in meinem Alter kann ich jeden Tag noch etwas dazulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31926] = { id = 31926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Antari", description = "Beim letzten Mal habt Ihr aus meinen Fehlern Kapital geschlagen, um den Sieg davonzutragen. Dieses Mal jedoch werdet Ihr weniger Glück haben, {race}.", sourceObjective = "Besiegt Blutritter Antari in einem Haustierkampf.", completion = "Ihr seid töricht, wenn Ihr glaubt, dass Ihr mir überlegen seid. Ich werde Euch zermalmen, das schwöre ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[31927] = { id = 31927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Nordend", description = "Die Besten der Scherbenwelt sind Eurer Fähigkeit zum Opfer gefallen, doch jetzt wartet Nordend auf Euch!\n\nVier Zähmer gilt es zu besiegen: Beegli Lunte im Heulenden Fjord, den fast kopflosen Jakob im Kristallsangwald, Okrut Drachenwüste in der Drachenöde und Darmwürger in Zul'Drak.\n\nWenn Ihr über sie alle triumphiert, wird der Großmeister Nordends mit seiner Herausforderung nicht lange auf sich warten lassen!", sourceObjective = "Besiegt Beegli Lunte, den fast kopflosen Jakob, Okrut Drachenwüste und Darmwürger in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31928] = { id = 31928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Payne", description = "Wenn Ihr mich fragt, haben meine Kollegen bei Eurer Ausbildung viel zu viel Nachsicht walten lassen.\n\nWenn man Haustiere wirklich zähmen will, ist militärische Disziplin gefordert. Ihr werdet die Ehre haben, selbst <Zeuge/Zeugin> dessen zu werden, was solche Disziplin bewirken kann.\n\nKommt zum Argentumturnierplatz in Eiskrone und seht selbst, was Ihr erreichen könntet!", sourceObjective = "Besiegt Major Payne in einem Haustierkampf.", completion = "Ich habe mich in Euch geirrt, {name}. Ihr seid einer der nobelsten Gegner, gegen die ich je die Ehre hatte zu kämpfen. Aber glaubt ja nicht, dass ich Euch beim nächsten Mal auch mit dem Sieg davonkommen lasse!", sourceObjectiveStatus = "unverified-source-field" }
quests[31929] = { id = 31929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Nordend", description = "Die Besten der Scherbenwelt sind Eurer Fähigkeit zum Opfer gefallen, doch jetzt wartet Nordend auf Euch!\n\nVier Zähmer gilt es zu besiegen: Beegli Lunte im Heulenden Fjord, den fast kopflosen Jakob im Kristallsangwald, Okrut Drachenwüste in der Drachenöde und Darmwürger in Zul'Drak.\n\nWenn Ihr über sie alle triumphiert, wird der Großmeister Nordends mit seiner Herausforderung nicht lange auf sich warten lassen!", sourceObjective = "Besiegt Beegli Lunte, den fast kopflosen Jakob, Okrut Drachenwüste und Darmwürger in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31930] = { id = 31930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Pandaria", description = "Jetzt müsst Ihr den zähesten Zähmern in ganz Azeroth gegenübertreten, {name}. Sie haben sich in Pandaria niedergelassen, der Heimat der Großmeister.\n\nSechs Großmeister gibt es noch zu besiegen: Hyuna von den Schreinen im Jadewald, Bäuerin Nishi im Tal der Vier Winde, Mo'ruk in der Krasarangwildnis, den mutigen Yon am Kun-Lai-Gipfel, Sucher Zusshi in der Tonlongsteppe und Ödniswandler Shu in der Schreckensöde.\n\nWenn Ihr glaubt, dass Ihr bereit seid, stellt Euch diesen Meistern ihres Fachs und beweist Euer Können!", sourceObjective = "Besiegt Hyuna von den Schreinen, Bäuerin Nishi, Mo'ruk, Yon den Mutigen, Sucher Zusshi und Ödniswandler Shu in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31931] = { id = 31931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beegli Lunte", description = "Eins von meinen Hühnern ist gestern ganz kurz geflogen. Ich schwör's. Endlich kommen wir ganz groß raus!\n\nAch, Ihr wollt schon wieder kämpfen?", sourceObjective = "Besiegt Beegli Lunte in einem Haustierkampf.", completion = "Eines Tages, wenn wir hoch über Euch fliegen, werdet Ihr unterliegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31932] = { id = 31932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fast kopfloser Jakob", description = "Ihr widersetzt Euch meiner Weisheit immer wieder. Was führt Euch in diese Wälder zurück?\n\nAch, Ihr wollt noch einmal kämpfen. Also gut.", sourceObjective = "Besiegt den fast kopflosen Jakob in einem Haustierkampf.", completion = "Euer Risiko hat sich bezahlt gemacht. Und jetzt fort mit Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[31933] = { id = 31933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okrut Drachenwüste", description = "Ihr wagt es, unsere Arbeit zu unterbrechen? Dann müsst Ihr erneut gegen mich kämpfen! Holt Eure Haustiere heraus, dann werde ich Euch Höllschreis Zorn schmecken lassen!", sourceObjective = "Besiegt Okrut Drachenwüste in einem Haustierkampf.", completion = "Ich fordere Euch heraus, das Unausweichliche zu bekämpfen. Die Drachen werden sich wieder nützlich für uns erweisen und Ihr werdet mir in einem Haustierkampf zur Hand gehen. Ich schwöre auf den Mantel des Kriegshäuptlings, dass es so sein wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[31934] = { id = 31934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darmwürger", description = "Ich Euch gerne bekämpfen. Ihr nicht so einfach wie andere. Wir nochmal kämpfen?", sourceObjective = "Besiegt Darmwürger in einem Haustierkampf.", completion = "Ich gerne gegen Euch kämpfen, auch, wenn ich verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31935] = { id = 31935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Payne", description = "<Dieser/Diese:c> rebellische {class} ist also wieder da, um <seine/ihre> Kräfte mit denen des Großmeisters zu messen. Dieses Mal wird Eure Kühnheit Euer Verderben sein!", sourceObjective = "Besiegt Major Payne in einem Haustierkampf.", completion = "Ich applaudiere Eurer Taktik, doch ich verachte Euren Sieg. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31936] = { id = 31936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bewässerungssystem \"Jinyuprinzessin\"", description = "<Auf der Rückseite der Kiste ist die Karikatur einer Jinyuprinzessin abgebildet, die vom folgenden Werbetext umrahmt wird:>\n\n\"Hallo, grüner Daumen! Knatschig über krass vertrocknete Kürbisse? Klagen über krustigen Kohl? Ist Euer Lauch lahm und sind Eure Melonen melancholisch?\n\nDann ist die Zeit gekommen, die Jinyuprinzessin nach Hause zu bringen! Sie wird Euren Garten wie feiner Frühlingsregen bewässern und die Dürre mit einem soliden Schluck...\"\n\n<Und so geht es sechs Absätze lang weiter.>", sourceObjective = "Bringt das Bewässerungssystem \"Jinyuprinzessin\" zu Bauer Yoon auf dem Gehöft Sonnensang oder dem Halbhügelmarkt.\n\nBereitgestellter Gegenstand:", completion = "Ein Bewässerungssystem? Für den Hof? Danke, {name}! Wir können es anstatt der alten Gießkanne verwenden.\n\nDie \"Jinyuprinzessin\"? Was hat es damit auf sich?\n\n\n\nNa gut, ich will es gar nicht wissen. Ich werde es sofort aufstellen lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31937] = { id = 31937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezieferschutz \"Donnerkönig\"", description = "<Das Ehrfurcht gebietende Konterfei eines Mogu prangt auf dieser Kiste; sein Blick ist auf die fein säuberlich darunter angeordneten fett gedruckten Zeilen gerichtet.>\n\n\"LASST EUCH EURE ERNTE NICHT DURCH SCHWACHE, EKEL ERREGENDE INSEKTEN VERDERBEN. WERDET IHRER DANK DER MACHT DES DONNERKÖNIGS HERR UND SCHÜTZT EUER ERBE.\"\n\n<Die übrige Fläche ist mit Karikaturen wehklagender oder verschreckt fliehender Insekten bedeckt.>", sourceObjective = "Bringt den Ungezieferschutz \"Donnerkönig\" zu Bauer Yoon auf dem Gehöft Sonnensang oder dem Halbhügelmarkt.\n\nBereitgestellter Gegenstand:", completion = "Schädlingsbekämpfungsmittel! Ihr seid genial, {name}! Endlich müssen wir uns nicht mehr mit diesem altmodischen Insektenvernichtungsmittel abgeben.\n\n\n\nOh ja, der Donnerkönig! So habe ich mir das vorgestellt!\n\nIch werde mich sofort damit an die Arbeit machen - diese Viecher werden nicht wissen, wie ihnen geschieht!", sourceObjectiveStatus = "unverified-source-field" }
quests[31938] = { id = 31938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der \"Erdschlitzer\"-Meisterpflug", description = "<Auf der Kiste ist ein Pandarenbauer mit einer unglaublichen Figur abgebildet, der voller Stolz mit gespreizten Beinen über einem breiter werdenden Riss im Boden steht und einen gewaltigen Pflug umklammert. Verspielte Junge tummeln sich auf seinen Schultern und baumeln von seinen muskulösen Armen.\n\nAn seiner Seite balanciert ein stoisches weibliches Wesen - mit ebenso unglaublicher Figur - ein gigantisches überschäumendes Füllhorn anmutig auf dem Kopf, während sie einem Shed-Ling einen Tritt ins Gesicht verpasst.>\n\n\"Der Erdschlitzer. Beherrscht das Land. Beherrscht Euer Leben.\"", sourceObjective = "Bringt den \"Erdschlitzer\"-Meisterpflug zu Bauer Yoon auf dem Gehöft Sonnensang oder dem Halbhügelmarkt.\n\nBereitgestellter Gegenstand:", completion = "Ein Erdschlitzer-Meisterpflug! Ich... ich hätte nie gedacht, dass ich jemals einen davon in die Hände bekommen würde. Ist Euch klar, wie viel Zeit wir damit sparen werden?!\n\nIch habe gehört, wenn Ihr mit dem Erdschlitzer zwanzig Meter solides Gestein durchpflügt, bekommt Ihr eine Sandkiste und eine Vorladung von den Shado-Pan für das Auslösen einer Erdbebenwarnung!\n\nDas wird der reine WAHNSINN.", sourceObjectiveStatus = "unverified-source-field" }
quests[31939] = { id = 31939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test", description = "Also gut – all Eure bisherige Feldarbeit war nur zum Üben da!\n\nSeid Ihr bereit, ein echter Ackerbauer zu werden?\n\nMei Mei Eisentatz drüben auf dem Markt braucht ein paar Karotten für ihren berühmten Eintopf. Und wisst Ihr, wer diese Karotten anbauen wird? Wir!\n\nWarum zeigt Ihr mir nicht, was Ihr bereits gelernt habt, indem Ihr vier Beete saftigleckere Karotten anpflanzt, pflegt und erntet?Ihr erlernt:", sourceObjective = "Pflanzt und erntet 4 saftigleckere Karotten. Saftigleckere Karottensamen können von Händler Grünfeld auf dem Halbhügelmarkt erworben werden. Nachdem Ihr Euren Ackerboden gepflügt und Euch um Eure Pflanzen gekümmert habt, müsst Ihr bis zum nächsten Tag warten, um Eure saftigleckeren Karotten ernten zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[31940] = { id = 31940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustiertrainer: Pandaria", description = "Die Besten der Scherbenwelt sind Euren Fertigkeiten zum Opfer gefallen, doch jetzt wartet Nordend auf Euch!\n\nVier Trainer gilt es zu besiegen: Ziggy den Flugunfähigen im Heulenden Fjord, den fast kopflosen Jakob im Kristallsangwald, Okrut Drachenwüste in der Drachenöde und Darmwürger in Zul'drak.\n\nWenn Ihr über sie alle triumphiert, wird der Großmeister Nordends mit seiner Herausforderung nicht lange auf sich warten lassen!", sourceObjective = "Besiegt Ziggy den Flugunfähigen, den fast kopflosen Jakob, Okrut Drachenwüste und Darmwürger in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31941] = { id = 31941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vierundsiebzig-elf: Kürbisch Wasser", description = "Großvater hat oft gesagt: \"Ein Kürbis pro Woche hilft, dass man nicht roche\".\n\n<Yoon schnüffelt fast unmerklich.>\n\nJawohl. Ich glaube, es ist ungefähr eine Woche her. Würdet Ihr mir helfen einen Jadekürbis zu pflanzen?", sourceObjective = "Pflanzt einen Jadekürbis auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Gut gepflanzt, {name}.\n\nUnd jetzt warten wir ab...", sourceObjectiveStatus = "unverified-source-field" }
quests[31942] = { id = 31942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melonensaison", description = "<Bauer Yoon schaut gen Himmel und schnuppert die Luft.>\n\nHmm...\n\n<Er leckt sich die Pfote und hält sie in die Brise, gräbt eine Zehe in den Boden und prüft dann die Länge seines Schattens.>\n\nJa. Die Melonensaison bricht an.\n\nKönntet Ihr mir ein paar Samen besorgen, damit ich Streifenmelonen anbauen kann?", sourceObjective = "Pflanzt eine Streifenmelone auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Das war knapp. Fast hätten wir die Melonensaison verpasst.", sourceObjectiveStatus = "unverified-source-field" }
quests[31943] = { id = 31943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häh? Beeren? Hexenbeeren.", description = "Der Junge dort drüben, Andi, wird irgendwann zu einem tollen Bauern heranwachsen. Das sehe ich auf einen Blick.\n\nIch glaube, ich werde ein paar Hexenbeeren für ihn pflanzen. Kinder lieben Hexenbeeren. Das wird eine nette Überraschung.", sourceObjective = "Pflanzt Hexenbeeren auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Hurra, Hexenbeeren! Ich kann es gar nicht erwarten!\n\nMuss ich aber.", sourceObjectiveStatus = "unverified-source-field" }
quests[31944] = { id = 31944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung abschließen: Die letzte Prüfung", description = "Willkommen zurück, {name}. Die Zeit ist gekommen, die letzte Phase Eurer Ausbildung zu absolvieren. Auf zum Ausbildungsgelände, damit Ihr Eure letzte Prüfung ablegen könnt.", sourceObjective = "Begebt Euch zum Ausbildungsgelände am Gipfel der Ruhe und legt Eure letzte Prüfung ab.", progress = "Absolviert Eure letzte Prüfung.", completion = "Gute Arbeit, {name}. Eure Ausbildung ist nun abgeschlossen. Kommt gerne auch in Zukunft wieder, um Eure Kräfte mit den Meistern hier zu messen und zu üben, was Ihr gelernt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31945] = { id = 31945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernen und Wachsen VI: Ginas Stimme", description = "Mein Geschäft ist dem Untergang geweiht! Seht Ihr all die Eisentatzen an ihren Kochstellen?\n\nIhre leckeren Gerichte locken viel Kundschaft zu diesem Markt, jetzt sind ihnen aber die Frühlingszwiebeln ausgegangen!\n\nSo unscheinbar sie sein mögen, Frühlingszwiebeln sind eine unentbehrliche Zutat beim Kochen. Ohne sie sind Gerichte weniger pikant, haben weniger Geschmack und weniger Aroma.\n\nEs ist eine Katastrophe. Und die nächste Lieferung Frühlingszwiebeln kommt erst nächste Woche!\n\nMoment mal. Ihr seid doch <Bauer/Bäuerin>, oder? Könnt Ihr mir vielleicht helfen?", sourceObjective = "Pflanzt 1 Frühlingszwiebel, erntet sie und bringt dann 5 Frühlingszwiebeln zu Gina Lehmkrall.\n\nFrühlingszwiebelsamen gibt es beim Händler Grünfeld auf dem Halbhügelmarkt zu kaufen. Nachdem Ihr Eure Pflanzen gepflanzt und gehegt habt, müsst Ihr bis zum nächsten Tag warten, um reife Frühlingszwiebeln ernten zu können.", progress = "Überseht die Frühlingszwiebel nicht. Sie mag klein und unscheinbar sein, doch sie schmeckt wahrlich phänomenal.", completion = "Ich fasse es nicht! Ich habe zwar schon größere Frühlingszwiebeln gesehen, die hier reichen aber völlig. Ihr habt gerade unsere Haut gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31946] = { id = 31946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mungs Stimme III: Die große Karottenkomödie", description = "Mung-Mung ist egal, wer Karotten stiehlt. Kümmert ihn nur, was Herr Lehmkrall armem Mung-Mung antut, wenn er sieht, dass seine Ernte ruiniert ist!\n\n<Mung-Mung kratzt sich gedankenverloren am Kinn.>\n\nHalt! Mung-Mung hat schlaue Idee. Geh und zieh wachsende saftigleckere Karotten. Dann nehmen wir Karotten und tun so, als wären es die von Herrn Lehmkrall.\n\nJawohl!", sourceObjective = "Pflanzt 2 saftigleckere Karotten, erntet sie und bringt dann 10 saftigleckere Karotten zu Mung-Mung.\n\nSaftigleckere Karottensamen gibt es beim Händler Grünfeld auf dem Halbhügelmarkt zu kaufen. Nachdem Ihr Eure Pflanzen gepflanzt und gehegt habt, müsst Ihr bis zum nächsten Tag warten, um reife saftigleckere Karotten ernten zu können.", progress = "Shed-Ling lieben Karotten, aber sie hassen Rüben. Ich hasse Rüben auch.", completion = "Boah, diese Karotten sehen knackig und saftig aus, {name}! Mung-Mung hatte keine Ahnung, dass du so einen grünen Daumen hast.", sourceObjectiveStatus = "unverified-source-field" }
quests[31947] = { id = 31947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauer Fungs Stimme III: Zum Wohl mit Kohl", description = "<Bauer Fung strahlt mit einem breiten Lächeln.>\n\nDank Euch habe ich meine kostbaren Yaks wieder! Leider musste ich feststellen, dass die Zeit in freier Wildbahn sie sehr ausgezehrt hat.\n\nAuch, wenn sie ganz ausgehungert sein müssen, kann ich nicht einfach gewöhnliches Gras an meine preisgekrönten Yaks verfüttern.\n\nNicht doch - sie fressen ausschließlich den üppigsten Grünkohl, der hier im Tal gedeiht.\n\nMeine Bestände gehen zur Neige. Wenn Ihr mir etwas Grünkohl für meine Yaks bringen könntet, werde ich Euch fürstlich belohnen.", sourceObjective = "Pflanzt und erntet 3 Grünkohle und bringt dann 15 Grünkohle zu Bauer Fung.\n\nIhr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben. Nach dem Beackern und Pflegen Eurer Pflanze müsst Ihr bis zum nächsten Tag warten, um den reifen Grünkohl zu ernten.", progress = "Ich habe Kosenamen für all meine Yaks. Da gibt es Pelzi, und Wolly; Flauschie und Kuschli und...", completion = "Ich habe Kohl erwartet, aber keinen Kohl dieser Güteklasse! Grundgütiger!\n\nPerfekte runde Form; große, speckige Blätter; herrlich changierende smaragdgrüne Farbe...\n\n<Bauer Fung beißt herzhaft in den Kohl.>\n\nMmm, und dieser süße, frische Geschmack! Das ist ein herrlicher Kohl, {name}. Meine Yaks werden diesen Leckerbissen zu schätzen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31948] = { id = 31948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nanas Stimme II: Die Heiligen Quellen", description = "Ihr kommt genau richtig, {name}. Ich will unbedingt frischen Hexenbeeren-Julep machen.\n\nHabt Ihr schon einmal von diesem wundersamen Gebräu gehört?\n\nJeder einzelne Schluck verjüngt Euer Gesicht um zehn Jahre! Was glaubt Ihr, warum ich noch so gut aussehe?\n\nWie dem auch sei, ich brauche eine besondere Zutat - tausend Jahre altes Wasser -, das an der Mündung des Wasserfalls im Norden besorgt werden kann.\n\nIch fürchte, für eine alte Dame wie mich ist die Reise zu beschwerlich, wenn Ihr allerdings einen Krug in die Hände bekommt, werde ich mein Gebräu mit Euch teilen.", sourceObjective = "Benutzt den leeren Krug am Goldfächer, um tausend Jahre altes Wasser zu sammeln.", progress = "Das Wasser in diesem Tal stammt aus dem Tal der Ewigen Blüten im Norden. Angeblich hat das Wasser hier wundersame, magische Eigenschaften.", completion = "Ihr habt die Fälle also gefunden? Oh ja, ich sehe, dass Ihr das Wasser gefunden habt. Großartig!", sourceObjectiveStatus = "unverified-source-field" }
quests[31949] = { id = 31949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nanas Stimme III: Hexenbeeren-Julep", description = "Jetzt, wo ich das Wasser habe, kann ich den eiskalten Hexenbeeren-Julep fast schon schmecken!\n\nJetzt müssen wir nur noch ein paar süße Hexenbeeren finden.\n\nDie Beeren meines Enkels waren dieses Jahr völlig unbrauchbar, deshalb muss ich anderswo nach einer vernünftigen Ernte suchen.\n\nIhr habt dieses Jahr nicht zufällig Hexenbeeren angebaut? Wie wär's denn, wenn Ihr mir welche von Eurem Hof bringen würdet?\n\nWenn Eure Beeren den Anforderungen entsprechen, stellen wir eine ganze Ladung von dem alten Gesöff her!", sourceObjective = "Pflanzt 3 Hexenbeeren, erntet sie und bringt dann 15 Hexenbeeren zu Nana Lehmkrall.\n\nHexenbeerensamen gibt es beim Händler Grünfeld auf dem Halbhügelmarkt zu kaufen. Nachdem Ihr Eure Pflanzen gepflanzt und gehegt habt, müsst Ihr bis zum nächsten Tag warten, um reife Hexenbeeren ernten zu können.", progress = "Beeilt Euch gefälligst! Ich bin eine alte Frau. Mir bleibt nicht viel Zeit und ich möchte die Soße noch einmal kosten, bevor ich abkratze!", completion = "<Nana Lehmkrall prüft eine dunkle Hexenbeere eingehend und steckt sie dann in den Mund. Ihr Gesicht erhellt sich.>\n\nDas Land lebt! Ich habe schon seit Jahren keine Hexenbeere mehr gegessen, die so süß und saftig war! Der einzige, der solche Beeren angebaut hat, war... der alte Yoon, der Großvater Eures Freundes.\n\n<Nana Lehmkrall wird rot.>\n\nOh, der Mann war vielleicht ein Schlingel! Ich kann mich noch an die Sommertage erinnern, als wir jung und unbeschwert waren und diese Beeren scheffelweise gegessen haben.\n\nDanke, dass Ihr mich an einen alten Freund erinnert habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31950] = { id = 31950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Move NPCs to Dais" }
quests[31951] = { id = 31951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Aki", description = "Ihr habt Euch gegen die Lehrer von Azeroth gut geschlagen. Selbst die Großmeister sind Eurer raffinierten Taktik zum Opfer gefallen.\n\nIch erwarte Euch jetzt im Tal der Ewigen Blüten, denn Ihr habt Euch das Privileg verdient, im Kampf gegen mich anzutreten. Los, {name}, zeigt, ob Ihr das Zeug habt, mich zu bezwingen.", sourceObjective = "Besiegt Aki die Auserwählte in einem Haustierkampf.", completion = "Ihr habt gesiegt. Setzt Eure Ausbildung fort und sucht bei anderen Lehrern wie Euch selbst nach Herausforderungen. Die Reise geht nie wirklich zu Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[31952] = { id = 31952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Pandaria", description = "Jetzt müsst Ihr den zähesten Zähmern in ganz Azeroth gegenübertreten, {name}. Sie haben sich in Pandaria niedergelassen, der Heimat der Großmeister.\n\nSechs Großmeister gibt es noch zu besiegen: Hyuna von den Schreinen im Jadewald, Bäuerin Nishi im Tal der Vier Winde, Mo'ruk in der Krasarangwildnis, den mutigen Yon am Kun-Lai-Gipfel, Sucher Zusshi in der Tonlongsteppe und Ödniswandler Shu in der Schreckensöde.\n\nWenn Ihr glaubt, dass Ihr bereit seid, stellt Euch diesen Meistern ihres Fachs und beweist Euer Können!", sourceObjective = "Besiegt Hyuna von den Schreinen, Bäuerin Nishi, Mo'ruk, Yon den Mutigen, Sucher Zusshi und Ödniswandler Shu in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31953] = { id = 31953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Hyuna", description = "Ihr möchtet erneut einen Kampf wagen? Nun gut. Er wird mich stärker machen, damit ich die geheiligten Stätten meines Volkes noch besser schützen kann.", sourceObjective = "Besiegt Hyuna von den Schreinen in einem Haustierkampf.", completion = "Ihr seid wahrlich stark. Werdet Ihr Eure Fertigkeiten meinen Bemühungen verschreiben?", sourceObjectiveStatus = "unverified-source-field" }
quests[31954] = { id = 31954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Mo'ruk", description = "Diesmal bin ich mit Gewinnen an der Reihe! Wartet's bloß ab!", sourceObjective = "Besiegt Mo'ruk in einem Haustierkampf.", progress = "Nein! Ich gewinne!", completion = "Nächstes Mal verliert Ihr. Ich werd Euch schlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31955] = { id = 31955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Nishi", description = "Die Stärke meiner Haustiere nimmt dank des fruchtbaren Landes, auf dem wir trainieren, immer weiter zu. Ihr habt keine Chance!", sourceObjective = "Besiegt Bäuerin Nishi in einem Haustierkampf.", completion = "Wow! Ich habe wohl nicht alleine trainiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[31956] = { id = 31956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Yon", description = "Wenn Ihr glaubt, dass ich Euch einfach so mit einem anderen Sieg davonkommen lasse, seid Ihr auf dem Holzweg. Dieses Mal werde ich mich als der bessere Trainer erweisen!", sourceObjective = "Besiegt Yon den Mutigen in einem Haustierkampf.", completion = "Schön. Ihr siegt also noch einmal. Jetzt ab mit Euch, ich habe vor unserem nächsten Zusammentreffen einiges an Vorbereitungen zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31957] = { id = 31957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Shu", description = "Ihr wagt Euch also erneut in die Tiefen der Wüste vor, um Euch mir zu stellen - nur werdet Ihr dieses Mal durch die Hand eines wahren Großmeisters zu Boden gestreckt werden. Edelmütig, aber töricht.", sourceObjective = "Besiegt Ödniswandler Shu in einem Haustierkampf.", completion = "In all meinen Jahren als Großmeister habe ich noch nie jemandem mit Eurer Entschlossenheit gegenübergestanden. Die anderen hatten recht, was Euch angeht. Ihr seid eine Größe, mit der man rechnen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[31958] = { id = 31958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Aki", description = "Ihr wollt Euch erneut an mir messen? Nun gut, lasst uns kämpfen.", sourceObjective = "Besiegt Aki die Auserwählte in einem Haustierkampf.", progress = "Die Reise zur Größe geht nie zu Ende.", completion = "Ihr seid stärker und Eure Fertigkeiten sind besser ausgeprägt. Eure Reise geht weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[31959] = { id = 31959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Trick der Kaiserin", description = "Großkaiserin Shek'zeer hat endgültig ihre Geduld mit uns verloren. Wir haben soeben erfahren, dass eine gewaltige Armee sich in den Schatten des Herzens der Angst zusammenzieht, mit dem Befehl, Klaxxi'vess zu vernichten.\n\nWir haben Glück gehabt, dass wir so lange ausgehalten haben, aber gegen eine Belagerung dieses Ausmaßes können wir nichts ausrichten.\n\n<Erwecker/Erweckerin>, Ihr wart von unschätzbarem Wert für uns. Geht, nehmt Euren Platz auf dem Schlachtfeld neben den Getreuen ein.\n\nIch sehe Euch dann auf dem Schlachtfeld!", sourceObjective = "Meldet Euch bei Malik dem Unversehrten vor dem Herzen der Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[31960] = { id = 31960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Vote #1 Complete" }
quests[31961] = { id = 31961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Vote #2 Complete" }
