quests[31965] = { id = 31965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Vote #6 Complete" }
quests[31966] = { id = 31966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Cataclysm", description = "Ihr habt die besten Zähmer von Nordend bezwungen, doch bevor Ihr es mit den Großmeistern Pandarias aufnehmen könnt, bedarf es weiterer Vorbereitungen. Macht Euch bereit und perfektioniert Eure Fertigkeiten weiter, indem Ihr folgende Zähmer besiegt: Brok in Hyjal, Bordin Ruhigfaust in Tiefenheim und Goz Unheilsfuror im Schattenhochland.\n\nWenn Ihr über sie triumphiert, seid Ihr bereit, die Reise nach Pandaria und Eurer ultimativen Herausforderung entgegen anzutreten.", sourceObjective = "Besiegt Brok, Bordin Ruhigfaust und Goz Unheilsfuror in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31967] = { id = 31967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Cataclysm", description = "Nordend hat sich Euch beugen müssen, doch noch seid Ihr nicht bereit, es mit den Großmeistern Pandarias aufzunehmen. Bezwingt folgende Zähmer, um Euren Willen für die vor Euch liegenden Herausforderungen zu stählen: Brok in Hyjal, Bordin Ruhigfaust in Tiefenheim und Goz Unheilsfuror im Schattenhochland.\n\nErst wenn Ihr sie bezwungen habt, seid Ihr bereit, nach Pandaria aufzubrechen.", sourceObjective = "Besiegt Brok, Bordin Ruhigfaust und Goz Unheilsfuror in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31968] = { id = 31968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweifel kommen auf", description = "Die Allianz... so viele Luftschiffe. Wie sollen wir die nur alle bekämpfen? Ich... mir geht es nicht gut...", sourceObjective = "Bringt Nazgrim dazu, sich zusammenzureißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31969] = { id = 31969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priorities Tracking" }
quests[31970] = { id = 31970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Obalis", description = "Ihr glaubt, Ihr seid bereit, Pandaria herauszufordern? Ihr glaubt wirklich, dass Ihr die mächtigsten Zähmer ganz Azeroths bezwingen könnt?\n\nÜberlasst das Urteil darüber nur mir, {race}. Stellt Euch mir auf dem Vir'naaldamm in Uldum, und es wird sich zeigen, ob Ihr wirklich bereit seid.", sourceObjective = "Besiegt Obalis in einem Haustierkampf.", completion = "Ich wurde eines Besseren belehrt. Ihr seid bereit, Euch meinen Meistern zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31971] = { id = 31971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Obalis", description = "Siehe da - <der triumphierende Zähmer/die triumphierende Zähmerin> will <seine/ihre> Kräfte mit den meinen messen. So sei es. Ich nehme die Herausforderung an.", sourceObjective = "Besiegt Obalis in einem Haustierkampf.", completion = "Durch jede meiner Niederlagen gewinne ich an Stärke. Nehmt Euch bei unserer nächsten Begegnung lieber in Acht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31972] = { id = 31972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brok", description = "Noch verstehe ich die Not dieser Geschöpfe nicht genug, um ihnen angemessen Hilfe leisten zu können. Ob ein weiterer Kampf unseren Bund wohl stärken könnte?", sourceObjective = "Besiegt Brok in einem Haustierkampf.", progress = "Stellt Euch mir im Kampf - zum Wohle des ganzen Hyjal.", completion = "Trotz meiner Niederlage spüre ich jetzt eine noch engere Verbindung zu meinen Tieren. Danke für einen würdigen Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31973] = { id = 31973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bordin Ruhigfaust", description = "Die Eingeborenen haben mich die Kraft der Erde gelehrt. Ich weiß um ihre unerschöpfliche Beständigkeit. Lasst uns ein Mal mehr kämpfen, und Ihr werdet sehen, dass ich zäher bin als je zuvor!", sourceObjective = "Besiegt Bordin Ruhigfaust in einem Haustierkampf.", completion = "Aber nein, ich hab's einfach vermasselt. Wie wär's mit einem neuen Versuch?", sourceObjectiveStatus = "unverified-source-field" }
quests[31974] = { id = 31974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goz Unheilsfuror", description = "Die Macht des Zwielichts durchdringt mich. Ich bin ein Gott! Ihr habt keine Chance, mich zu besiegen!", sourceObjective = "Besiegt Goz Unheilsfuror in einem Haustierkampf.", progress = "Armseliger {race}. Verdammt dazu, machtlos den Tod durch die Hand der Herrscher dieser Welt in Kauf zu nehmen.", completion = "Ihr kämpft mit dem Zorn meiner Meister. Vielleicht sind wir beide doch nicht so verschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31975] = { id = 31975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Wenn Ihr mich fragt, gehört Ihr in die Scherbenwelt, zusammen mit den anderen Hitzköpfen. Warum geht Ihr nicht wieder zu Marlene Trichdie in Sturmwind und findet heraus, was Eure neue Karriere als <Zähmer/Zähmerin> als Nächstes bereithält?", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Dann wollen wir sehen... wohin wir Euch als Nächstes senden...", sourceObjectiveStatus = "unverified-source-field" }
quests[31976] = { id = 31976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Die Kunde von Eurem Können verbreitet sich. Ich schlage vor, Ihr kehrt für weitere Unterweisung zu Eurer Trainerin Marlene Trichdie zurück.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Dann wollen wir sehen... wohin wir Euch als Nächstes senden...", sourceObjectiveStatus = "unverified-source-field" }
quests[31977] = { id = 31977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Wenn Ihr mich fragt, gehört Ihr in die Scherbenwelt, zusammen mit den anderen Hitzköpfen. Warum kehrt Ihr nicht zu Varzok in Orgrimmar zurück und findet heraus, was Eure neue Karriere als <Zähmer/Zähmerin> als Nächstes bereithält?", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Ich habe Eure nächsten Herausforderungen vorbereitet, {name}. Zeigt uns, ob Ihr auf sie vorbereitet seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[31978] = { id = 31978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prioritäten!", description = "Seht Euch bloß diese Sauerei an! Das ganze Bräu ist verdorben!\n\nTaran Zhu hat uns davor gewarnt mit Euch Außenseitern zu sprechen, ich nehme aber jede Hilfe an, die ich bekommen kann.\n\nWir waren nach Morgenblüte unterwegs, um unser Bräu abzuliefern, als der Kampf ausbrach. Und jetzt ist unser ganzes Bräu dahin!\n\nWollt Ihr es wiedergutmachen? Vielleicht findet Ihr ja ein paar Fässer mit Honigbräu, die nicht kaputt sind. Dann wäre nicht alles verloren.", sourceObjective = "Findet 6 Fässer mit Honigbräu auf der Honigtaulichtung.", completion = "Es ist nicht so viel wie ich gehofft hatte, doch es wird schon reichen. Hat wohl keinen Sinn, verschüttetem Bräu nachzutrauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[31979] = { id = 31979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Wenn Ihr mich fragt, gehört Ihr in die Scherbenwelt, zusammen mit den anderen Hitzköpfen. Warum geht Ihr nicht wieder zu Marlene Trichdie in Sturmwind und findet heraus, was Eure neue Karriere als <Zähmer/Zähmerin> als Nächstes bereithält?", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31980] = { id = 31980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Die Kunde von Eurem Können verbreitet sich. Ich schlage vor, Ihr kehrt für weitere Unterweisung zu Eurem Trainer Varzok zurück.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Ich glaube, ich kenne genau den Ort, um Euch als Nächstes zu prüfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31981] = { id = 31981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übertroffene Erwartungen", description = "Ab mit Euch zu Eurer Trainerin Marlene Trichdie in Sturmwind. Vielleicht hat sie ein paar... lohnende... Herausforderungen in petto für Euch.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Ihr habt wirklich Großmeister Antari bezwungen? Wow! Ich werde ein paar wirklich hartgesottene Zähmer finden müssen, die es mit Euch aufnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31982] = { id = 31982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übertroffene Erwartungen", description = "Ab mit Euch zu Eurem Trainer Varzok in Orgrimmar. Vielleicht hat er ein paar... lohnende... Herausforderungen in petto für Euch.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Es gibt nur einen Ort, an dem Eure nächste Prüfung stattfinden könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[31983] = { id = 31983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kurzer Aufschub", description = "Nicht schlecht, wenn man bedenkt, dass Ihr <ein/eine:r> {race} seid. Und jetzt zurück nach Orgrimmar. Sprecht mit diesem Grobian Varzok. Hoffentlich schickt er Euch an irgendeinen Ort, der sich möglichst weit von meiner Familie entfernt befindet.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Ich glaube, ich weiß, was Ihr als Nächstes unternehmen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31984] = { id = 31984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kurzer Aufschub", description = "Gute Arbeit, wirklich gute Arbeit! Könntet Ihr wohl Fräulein Marlene Trichdie in Sturmwind darüber berichten?\n\nOh, und bestellt Ihr schöne Grüße von mir. Eine schöne junge Dame wie sie könnte von der Begleitung eines erfahrenen Kämpfers wie mir wirklich profitieren.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Payne hat Euch gebeten, Euch für ihn an mich heranzumachen, stimmt's? Wann begreift er es endlich?", sourceObjectiveStatus = "unverified-source-field" }
quests[31985] = { id = 31985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die triumphale Rückkehr", description = "Ihr seid jetzt so vorbereitet, wie Eure Trainerin das wollte. Kehrt nach Sturmwind zurück und sprecht mit Marlene Trichdie. Sie wird Euch weiter unterweisen.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Ihr habt also Obalis kennengelernt? Unter seiner rauen Schale ist er ein toller Bursche.", sourceObjectiveStatus = "unverified-source-field" }
quests[31986] = { id = 31986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die triumphale Rückkehr", description = "Ihr seid jetzt so vorbereitet, wie Euer Trainer das wollte. Kehrt nach Orgrimmar zurück und sprecht mit Varzok. Er wird Euch weiter unterweisen.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Ihr seid jetzt auf eine echte Prüfung Eures Könnens im Kampf vorbereitet. Seid Ihr soweit?", sourceObjectiveStatus = "unverified-source-field" }
quests[31987] = { id = 31987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Theramore Launch Event" }
quests[31988] = { id = 31988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tägliche Szenarioauswahl" }
quests[31989] = { id = 31989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel der Ruhe - Schließt Eure Ausbildung ab", description = "Es ist Zeit, dass Ihr zum Gipfel der Ruhe zurückkehrt, um Eure Ausbildung abzuschließen. Kehrt mithilfe der Zenpilgerfahrt dorthin zurück und sprecht bei Eurer Ankunft mit Meister Hight.", sourceObjective = "Reist mithilfe der Zenpilgerfahrt zum Gipfel der Ruhe. Sprecht bei Eurer Ankunft mit Meister Hight am Schrein des Ochsen.", completion = "Willkommen, {name}. Zeit für den letzten Schritt Eurer Ausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31990] = { id = 31990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marlene Trichdie", description = "Ich kann Euch nichts mehr beibringen, {name}. Eure Trainerkarriere jedoch hat gerade erst begonnen!\n\nSucht Marlene Trichdie in Sturmwind auf. Sie steht mit der Elite unter Azeroths Trainern in Verbindung und wird Eurer Entwicklung förderlich sein.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31991] = { id = 31991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Zusshi", description = "Ich wusste, dass Ihr zurückkommen würdet, um noch einmal gegen mich anzutreten. Dann wollen wir sehen, wer im Kampf weiser ist.", sourceObjective = "Besiegt Sucher Zusshi in einem Haustierkampf.", completion = "Ihr seid tatsächlich überlegen. Wenn Ihr mich entschuldigen würdet - ich muss den See um Rat zu meiner Niederlage bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31998] = { id = 31998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Sha des Zweifels", description = "{name}, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in den Tempel der Jadeschlange führen. Aktiviert die Kugel des Herausforderers und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Tempel der Jadeschlange im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31999] = { id = 31999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazgrims Befehl", description = "Ihr habt hier eine schöne Basis. Von der Allianz ist weit und breit nichts zu sehen, und dazu habt Ihr noch einige Veteranen der Horde zur Seite. Ich würde sagen, es ist an der Zeit, diesen Kontinent rot zu färben.\n\nGeneral Nazgrim wird wissen, wie unser erster Schritt aussieht.", sourceObjective = "Meldet Euch bei General Nazgrim auf dem Starkarmflugplatz im Jadewald.", completion = "Wir mögen zwar die Schlacht gegen die Allianz gewonnen haben, aber das bringt uns mit den ganzen Plapperaffen in unserem Gebiet auch nicht weiter.\n\nDie Ho-zen sind unser nächstes Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32000] = { id = 32000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Yan-Zhu der Dekantierte", description = "{name}, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in die Brauerei Sturmbräu führen. Aktiviert die Kugel des Herausforderers und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt die Brauerei Sturmbräu im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32001] = { id = 32001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Sha des Hasses", description = "{name}, Ihr müsst eine abgeklärte Gruppe zusammenstellen und sie ins Shado-Pan-Kloster führen. Aktiviert die Kugel des Herausforderers und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Shado-Pan-Kloster im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32002] = { id = 32002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Xin der Waffenmeister", description = "{name}, Ihr müsst eine geschickte Gruppe zusammenstellen und sie in den Mogu'shanpalast führen. Aktiviert die Kugel des Herausforderers und bereitet Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Mogu'shanpalast im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32003] = { id = 32003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Raigonn", description = "{name}, Ihr müsst eine entschlossene Gruppe zusammenstellen und sie zum Tor der Untergehenden Sonne führen. Aktiviert die Kugel des Herausforderers und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Tor der Untergehenden Sonne im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32004] = { id = 32004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Schwadronsführer Ner'onok", description = "{name}, Ihr müsst eine scharfsichtige Gruppe zusammenstellen und sie zur Belagerung des Niuzaotempels führen. Aktiviert die Kugel des Herausforderers und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Niuzaotempel im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32005] = { id = 32005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Durand", description = "{name}, Ihr müsst eine tapfere Gruppe zusammenstellen und sie in das Scharlachrote Kloster führen. Aktiviert die Kugel des Herausforderers und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Scharlachrote Kloster im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32006] = { id = 32006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Flammenwirker Koegler", description = "{name}, Ihr müsst eine gewitzte Gruppe zusammenstellen und sie in die Tiefen der Scharlachroten Hallen führen. Aktiviert die Kugel des Herausforderers und setzt dem bücherverbrennenden Treiben von Flammenwirker Koegler ein Ende.", sourceObjective = "Schließt die Scharlachroten Hallen im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32007] = { id = 32007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Dunkelmeister Gandling", description = "{name}, Ihr müsst eine furchtlose Gruppe zusammenstellen und sie in die Tiefen von Scholomance führen. Aktiviert die Kugel des Herausforderers und reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt Scholomance im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32008] = { id = 32008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marlene Trichdie", description = "Seid gegrüßt, {name}! Ich bin Marlene Trichdie. Man hört in letzter Zeit ziemlich viel von Euch. Ihr scheint zu <einem hervorragenden Zähmer/einer hervorragenden Zähmerin> heranzureifen!\n\nIhr solltet Euch mit mir in Sturmwind auf ein Gespräch treffen. Ich stehe mit den besten Zähmern in ganz Azeroth in Verbindung und kann Euch helfen, noch besser zu werden!", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Ach, Ihr seid {name}. Wunderbar! Dann machen wir uns gleich an die Arbeit, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[32009] = { id = 32009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Lok'tar, {name}. Mein Name ist Varzok, und ich habe in letzter Zeit viel von Euren Leistungen als <Zähmer/Zähmerin> gehört. Ich möchte Euch gerne Trainern in ganz Azeroth vorstellen, damit Ihr Eure Fertigkeiten weiter verbessern könnt.\n\nBitte trefft Euch auf ein Gespräch mit mir in Orgrimmar, auf dass wir alles in die Wege leiten können.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Ihr müsst {name} sein. Schön, Eure Bekanntschaft zu machen. Ich bin Varzok.\n\nIch werde von nun an Eure Kontaktperson sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32010] = { id = 32010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Celestial Task" }
quests[32011] = { id = 32011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine himmlische Aufgabe", description = "Habt Ihr schon von den Himmlischen Erhabenen gehört? Yu'lon, Chi-Ji, Xuen, und Niuzao wachen über ganz Pandaria.\n\nUnd sie wachen auch über Euch.\n\nIhr Wissen ist uralt und sehr mächtig. Jenen, die in ihrer Gunst stehen, können sie große Macht verleihen.\n\nIhr mögt danach streben, ihr Vertrauen zu gewinnen, doch sie brauchen in einer wichtigeren Angelegenheit Eure Hilfe.\n\nDas Tal der Ewigen Blüten ist in Gefahr. Wir müssen zuerst das Tal retten, bevor wir uns wieder den Himmlischen selbst zuwenden können.", sourceObjective = "Erlangt beim Goldenen Lotus einen respektvollen Ruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[32012] = { id = 32012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kovok tracking [GROWING]" }
quests[32016] = { id = 32016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrwürdige Amulette des Glücks", description = "Seid gegrüßt, {name}. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einem ehrwürdigen Amulett des Glücks werden wertvolle Artefakte sehr viel häufiger in Euren Besitz gelangen.", sourceObjective = "Sammelt 90 geringe Amulette des Glücks.", sourceObjectiveStatus = "unverified-source-field" }
quests[32017] = { id = 32017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrwürdige Amulette des Glücks", description = "Seid gegrüßt, {name}. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einem ehrwürdigen Amulett des Glücks werden wertvolle Artefakte sehr viel häufiger in Euren Besitz gelangen.", sourceObjective = "Sammelt 90 geringe Amulette des Glücks.", sourceObjectiveStatus = "unverified-source-field" }
quests[32018] = { id = 32018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Name war Sturmbräu", description = "Ein außergewöhnlicher Pandaren machte vor einigen Tagen Zwischenstation in der Stadt. Er erzählte bessere Geschichten als Pan, trank doppelt so viel wie Li und hat mich zum Abschluss noch vor der Taverne verprügelt. Und nebenher hat sich seine kleine Nichte über uns lustig gemacht.\n\nEs war einfach toll.\n\nSie sagten, dass sie ins Tal der Vier Winde reisen wollten. Ihr solltet ihn kennenlernen! Hütet Euch nur vor seinem rechten Haken.", sourceObjective = "Sprecht mit Chen Sturmbräu auf den Donnerfußfeldern im Tal der Vier Winde.", completion = "Ha ha! Bolo hat Euch geschickt? Der \"Fassflüsterer\", stimmt's? Aus dem Betrunkenen Ho-zen?\n\nWie geht es seinem Auge? Und ist sein Freund immer noch verkatert?\n\nAch, das war mal ein schöner Abend.", sourceObjectiveStatus = "unverified-source-field" }
quests[32019] = { id = 32019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie nennen ihn Sturmbräu", description = "Die Lage war nicht immer so, {race}. Oh nein, sie war sogar noch viel schlimmer. Vor gerade einmal drei Wochen wurden wir von Saurokbanditen belagert. Sie haben unsere Jade gestohlen, unsere Nahrungsmittelvorräte besudelt und unsere Jungen terrorisiert.\n\nWir brauchten einen Helden, und der sollte auch kommen.\n\nEr schlug ihre Streitkräfte zurück, besiegte ihren Anführer und brachte uns die gestohlene Jade zurück. Und zum Dank wollte er nichts weiter als einen Schlangenritt für seine Nichte.\n\nIch hatte nie die Gelegenheit, ihm richtig zu danken. Wenn Ihr ins Tal der Vier Winde geht, könntet Ihr ihm unseren Dank ausrichten?", sourceObjective = "Sprecht mit Chen Sturmbräu auf den Donnerfußfeldern im Tal der Vier Winde.", completion = "Ihr kommt vom Tempel der Jadeschlange? Ren-Zhu lässt seinen Dank ausrichten?\n\nNun, äh... es war wirklich nichts. Ich hätte diesen Saurok besiegen können, ohne einen Tropfen Bräu zu verschütten.\n\nIch glaube, das habe ich sogar.", sourceObjectiveStatus = "unverified-source-field" }
quests[32020] = { id = 32020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
