quests[32035] = { id = 32035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seide macht's!", description = "Von den Seidenfeldern hört man merkwürdige Geräusche.\n\nUnd auch seltsame Gerüche ziehen von dort herüber.\n\n<Ein abgebrannter/Eine abgebrannte:c> {class} wie Ihr könnte ihnen vielleicht etwas aushelfen und sich dabei ein paar Goldstücke verdienen.\n\n... Oder auch nicht.", sourceObjective = "Meldet Euch bei Seidenmeister Tsai auf den Seidenfeldern im Tal der Vier Winde.", completion = "Seid gegrüßt, {class}. Willkommen in den Seidenfeldern.", sourceObjectiveStatus = "unverified-source-field" }
