quests[32038] = { id = 32038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hirschmeister", description = "Für eine schöne Hirschjagd bin ich immer zu haben. Es sind zähe und schnelle Tiere, die ihr Revier verteidigen.\n\nSie mögen zwar Pflanzenfresser sein, doch können sie selbst den erfahrensten Jäger in die Flucht schlagen.\n\nÖstlich von hier ist ein ganzes Rudel Wildlandhirsche, das nur darauf wartet von <einem Jäger/einer Jägerin> wie Euch etwas aufgescheucht zu werden.\n\nGute Jagd!", sourceObjective = "Tötet 10 Wildlandhirsche.", completion = "Eine so gute Hirschjagd habe ich seit dem Eschental nicht gesehen.", sourceObjectiveStatus = "unverified-source-field" }
